export function getARMLAProfile(acNo: number): MLAProfile | undefined {
  return AR_MLA_PROFILES.find(p => p.acNo === acNo);
}

export function getARMLAsByParty(party: string): MLAProfile[] {
  return AR_MLA_PROFILES.filter(p => p.party === party);
}

export function getARFemaleMLAs(): MLAProfile[] {
  return AR_MLA_PROFILES.filter(p => p.gender === 'F');
}
